function parseComment(raw) {
  const body = String(raw || '').split('\n').filter((l) => !l.trim().startsWith('>')).join('\n').trim();
  const first = body.match(new RegExp(`^\\[(${COMMENT_TAGS})\\]\\s*([\\s\\S]*)$`, 'i'));
